import type { components, operations } from './api-types.js';

/**
 * Named aliases of the generated OpenAPI schemas (`api-types.ts`, regenerated by
 * `pnpm --filter @power-budget/shared-app codegen`). Web and mobile import API shapes
 * from here instead of declaring their own copies.
 */
type Schemas = components['schemas'];
/** The query parameters of an operation, as the API documents them (`@ApiQueryFrom`, CLN-050). */
type QueryOf<K extends keyof operations> = NonNullable<operations[K]['parameters']['query']>;

// Query parameters
export type ListPlansQueryDto = QueryOf<'PlansController_list'>;
export type ListTransactionsQueryDto = QueryOf<'TransactionsController_list'>;
export type ListAuditLogQueryDto = QueryOf<'AuditController_list'>;
export type ListCategoriesQueryDto = QueryOf<'CategoriesController_list'>;
export type GetCatalogQueryDto = QueryOf<'BankController_catalogue'>;

// Money and dates
export type MoneyDto = Schemas['MoneyDto'];
export type DateRangeDto = Schemas['DateRangeDto'];

// Auth
export type RegisterDto = Schemas['RegisterDto'];
